/// <summary>
/// Boss 地面重击：以施法者为中心，圆形 AoE 伤害 + 短暂眩晕玩家。
/// </summary>
[CreateAssetMenu(fileName = "GroundSmash", menuName = "Game/Skill Effect/Ground Smash")]
public class BossSkill_GroundSmash : SkillEffectBase
{
    [Header("范围")]
    public float radius = 3.5f;
    public float warningDuration = 0.5f;

    [Header("眩晕")]
    [Tooltip("玩家被击中后无法输入的时间 (秒)")]
    public float stunDuration = 0.5f;

    [Header("特效")]
    public GameObject warningVfx;

    public override void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType)
    {
        Vector2 center = caster.CasterTransform.position;
        float damage = caster.GetAttackStrength() * damageMultiplier;

        MonoBehaviour mono = caster.CasterTransform.GetComponent<MonoBehaviour>();
        if (mono == null) return;

        mono.StartCoroutine(SmashRoutine(caster, center, damage, ownerType));
    }

    private System.Collections.IEnumerator SmashRoutine(ISkillCaster caster, Vector2 center,
                                                          float damage, Projectile.OwnerType ownerType)
    {
        // 预警
        if (warningVfx != null)
            Object.Instantiate(warningVfx, center, Quaternion.identity);

        yield return new WaitForSeconds(warningDuration);

        // 伤害
        string enemyTag = ownerType == Projectile.OwnerType.Player ? "Enemy" : "Player";
        Collider2D[] hits = Physics2D.OverlapCircleAll(center, radius);
        foreach (var hit in hits)
        {
            if (!hit.CompareTag(enemyTag)) continue;
            if (hit.TryGetComponent<IDamageable>(out var d))
                d.TakeDamage(damage);

            // 眩晕玩家
            if (hit.CompareTag("Player") && hit.TryGetComponent<PlayerController>(out var pc))
                pc.StartCoroutine(StunPlayer(pc));
        }
    }

    private System.Collections.IEnumerator StunPlayer(PlayerController pc)
    {
        pc.InputLocked = true;
        yield return new WaitForSeconds(stunDuration);
        pc.InputLocked = false;
    }
}

using UnityEngine;

/// <summary>
/// Boss 召唤技能：在施法者周围随机位置生成小怪。
/// </summary>
[CreateAssetMenu(fileName = "Summon", menuName = "Game/Skill Effect/Summon")]
public class BossSkill_Summon : SkillEffectBase
{
    [Header("召唤")]
    [Tooltip("可召唤的敌人预制体池")]
    public GameObject[] enemyPrefabs;

    [Tooltip("召唤数量")]
    public int count = 3;

    [Tooltip("生成半径 (围绕施法者)")]
    public float spawnRadius = 4f;

    [Tooltip("生成间隔 (秒)")]
    public float spawnInterval = 0.3f;

    public override void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType)
    {
        MonoBehaviour mono = caster.CasterTransform.GetComponent<MonoBehaviour>();
        if (mono == null) return;
        mono.StartCoroutine(SummonRoutine(caster));
    }

    private System.Collections.IEnumerator SummonRoutine(ISkillCaster caster)
    {
        if (enemyPrefabs == null || enemyPrefabs.Length == 0) yield break;

        Vector2 center = caster.CasterTransform.position;

        // 找到当前房间的 Transform 作为父节点
        Transform parent = caster.CasterTransform.parent;

        for (int i = 0; i < count; i++)
        {
            Vector2 offset = Random.insideUnitCircle * spawnRadius;
            Vector2 spawnPos = center + offset;

            GameObject prefab = enemyPrefabs[Random.Range(0, enemyPrefabs.Length)];
            if (prefab == null) continue;

            var go = Object.Instantiate(prefab, spawnPos, Quaternion.identity, parent);
            go.name = $"Summon_{i}_{prefab.name}";

            yield return new WaitForSeconds(spawnInterval);
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 敌人的技能管理组件：负责装配技能、驱动冷却并提供 TryCast 接口。
/// </summary>
public class EnemySkillManager : MonoBehaviour
{
    private List<SkillInstance> _skillInstances = new List<SkillInstance>();

    public IReadOnlyList<SkillInstance> SkillInstances => _skillInstances;

    public void InitializeFromLibrary(SkillLibrary library, int randomMin = 1, int randomMax = 2)
    {
        _skillInstances.Clear();
        if (library == null) return;

        var datas = library.GetRandomDistinct(Random.Range(randomMin, randomMax + 1));
        foreach (var d in datas)
        {
            if (d == null) continue;
            var inst = library.CreateSkillInstance(d.skillId);
            if (inst != null) _skillInstances.Add(inst);
        }
    }

    private void Update()
    {
        float dt = Time.deltaTime;
        foreach (var s in _skillInstances)
            s.TickCooldown(dt);
    }

    public bool TryCastSkill(int index, ISkillCaster caster, Vector2 dir)
    {
        if (index < 0 || index >= _skillInstances.Count) return false;
        return _skillInstances[index].TryCast(caster, dir);
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 敌人聚合门面：实现 IEnemy / IDamageable / ISkillCaster，自动收集子组件并负责连线。
/// 所有对外系统（Spawner、技能效果等）应依赖 IEnemy 接口。
/// </summary>
[DisallowMultipleComponent]
public class EnemyCore : MonoBehaviour, IEnemy
{
    [Header("配置")]
    public EnemyConfig config;

    // 子组件
    public EnemyHealth Health { get; private set; }
    public EnemyMovement Movement { get; private set; }
    public EnemySkillManager SkillManager { get; private set; }
    public EnemyStateMachine StateMachine { get; private set; }
    public IAttackBehavior AttackBehavior { get; private set; }

    // 缓存玩家引用 + 最后已知位置（供状态机读取）
    public Transform PlayerTarget { get; private set; }
    public Vector2 LastKnownPlayerPosition { get; set; }

    public Transform EnemyTransform => transform;
    public bool IsDead => Health != null && Health.IsDead;
    public bool IsAssimilated { get; private set; }
    public IReadOnlyList<SkillInstance> SkillInstances => SkillManager != null ? SkillManager.SkillInstances : new List<SkillInstance>();
    public event Action OnDied;
    public event Action<IEnemy> OnAssimilated;

    private void Awake()
    {
        Health = GetComponent<EnemyHealth>();
        Movement = GetComponent<EnemyMovement>();
        SkillManager = GetComponent<EnemySkillManager>();
        StateMachine = GetComponent<EnemyStateMachine>();
        AttackBehavior = GetComponent<IAttackBehavior>();

        if (Health == null) Health = gameObject.AddComponent<EnemyHealth>();
        if (Movement == null) Movement = gameObject.AddComponent<EnemyMovement>();
        if (SkillManager == null) SkillManager = gameObject.AddComponent<EnemySkillManager>();
        if (StateMachine == null) StateMachine = gameObject.AddComponent<EnemyStateMachine>();

        // ═══ 单一数据源：EnemyConfig → EnemyCore → 各组件 ═══
        if (config != null)
        {
            if (Health != null)
            {
                Health.MaxHealth = config.maxHealth;
                Health.Initialize();
            }

            if (Movement != null)
                Movement.MoveSpeed = config.patrolSpeed;

            if (SkillManager != null)
                SkillManager.InitializeFromLibrary(config.skillLibrary);
        }
        else if (Health != null)
        {
            // 无 config 时，允许组件自身的 MaxHealth 作为默认值
            Health.Initialize();
        }

        // 绑定死亡事件
        if (Health != null)
        {
            Health.OnDied += () =>
            {
                OnDied?.Invoke();
                // 切换到死亡状态
                if (StateMachine != null)
                    StateMachine.ChangeState(new DeadState(this));
            };
        }
    }

    private void Start()
    {
        var player = GameObject.FindGameObjectWithTag("Player");
        if (player != null) PlayerTarget = player.transform;

        // 启动默认状态（若存在巡逻点则 Patrol，否则 Idle）
        if (StateMachine != null)
        {
            if (config != null && config.patrolPoints != null && config.patrolPoints.Count > 0)
                StateMachine.ChangeState(new PatrolState(this));
            else
                StateMachine.ChangeState(new IdleState(this));
        }
    }

    // ---------- IDamageable (门面) ----------
    public void TakeDamage(float damage)
    {
        if (Health != null)
            Health.TakeDamage(damage);
    }

    // ---------- ISkillCaster ----------
    public Transform CasterTransform => transform;

    public Vector2 GetTargetDirection()
    {
        if (PlayerTarget == null) return Vector2.down;
        return (PlayerTarget.position - transform.position).normalized;
    }

    public float GetAttackStrength()
    {
        // 优先从 MeleeAttack 组件读取伤害值
        if (AttackBehavior is MeleeAttack melee)
            return melee.damage;
        if (AttackBehavior is RangedAttack ranged)
            return ranged.damage;
        return 10f;
    }

    /// <summary>
    /// 施法者阵营：被同化后为 Player（技能命中 Enemy），否则为 Enemy（技能命中 Player）。
    /// </summary>
    public Projectile.OwnerType GetOwnerType() =>
        IsAssimilated ? Projectile.OwnerType.Player : Projectile.OwnerType.Enemy;

    // ---------- 同化 ----------
    /// <summary>
    /// 将被侵蚀的敌人转化为玩家的随从。
    /// - 改 tag 为 Player（让其他敌人的攻击能命中此随从）
    /// - 禁用原状态机，由 EnemyFollower 接管 AI
    /// - 清除旧的死亡事件，由 EnemyFollower 处理死亡
    /// </summary>
    public void Assimilate(Transform playerTarget)
    {
        // 1. 标记已同化（房间/生成器通过 OnAssimilated 事件从存活列表移除）
        IsAssimilated = true;

        // 2. 清除旧的死亡订阅（由 EnemyFollower 接管死亡处理）
        if (Health != null)
            Health.ClearOnDied();

        // 3. 通知外部系统：此敌人不再是敌人
        OnAssimilated?.Invoke(this);

        // 4. 改 tag，使敌人攻击能命中此随从
        gameObject.tag = "Player";

        // 5. 禁用原有状态机
        if (StateMachine != null)
            StateMachine.enabled = false;

        // 6. 停止当前移动
        Movement?.Stop();

        // 7. 添加并激活随从组件
        EnemyFollower follower = GetComponent<EnemyFollower>();
        if (follower == null)
            follower = gameObject.AddComponent<EnemyFollower>();
        follower.Activate(playerTarget);

        // 8. 更新玩家引用（供技能方向等使用）
        PlayerTarget = playerTarget;
    }
}

using UnityEngine;

/// <summary>
/// 随从行为组件：接管被同化敌人的 AI，跟随玩家 + 搜索并攻击其他敌人。
/// 由 EnemyCore.Assimilate() 激活。
/// </summary>
[RequireComponent(typeof(EnemyCore))]
public class EnemyFollower : MonoBehaviour
{
    [Header("随从参数")]
    [SerializeField] private float _followDistance = 2f;
    [SerializeField] private float _detectionRange = 8f;
    [SerializeField] private float _attackRange = 2f;
    [SerializeField] private float _followSpeed = 3f;
    [Tooltip("离玩家超过此距离时直接传送到身边，防止掉队")]
    [SerializeField] private float _maxTeleportDistance = 12f;

    private Transform _player;
    private EnemyCore _core;
    private EnemyMovement _movement;
    private IAttackBehavior _attackBehavior;
    private EnemySkillManager _skillManager;
    private bool _isActive;

    /// <summary>所有活跃随从列表（供 MapManager 查询，避免 FindObjectsByType）</summary>
    public static readonly System.Collections.Generic.List<EnemyFollower> ActiveFollowers = new();

    private void OnEnable()
    {
        ActiveFollowers.Add(this);

        // 订阅房间切换事件——每次 OnEnable 都重新订阅，确保 SetParent 导致的
        // OnDisable→OnEnable 周期后仍然能响应后续房间切换。
        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchStarted += OnRoomSwitchStarted;
    }

    private void OnDisable()
    {
        ActiveFollowers.Remove(this);
        if (_core != null && _core.Health != null)
            _core.Health.OnDied -= HandleDeath;
        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchStarted -= OnRoomSwitchStarted;
    }

    private void Awake()
    {
        _core = GetComponent<EnemyCore>();
    }

    /// <summary>
    /// 激活随从模式。
    /// </summary>
    public void Activate(Transform player)
    {
        _player = player;
        _isActive = true;

        _movement = _core.Movement;
        _attackBehavior = _core.AttackBehavior;
        _skillManager = _core.SkillManager;

        if (_movement != null)
            _movement.MoveSpeed = _followSpeed;

        // 远程攻击的随从需要以 OwnerType.Player 发射投射物，才能命中 Enemy tag
        if (_attackBehavior is RangedAttack ranged)
            ranged.projectileOwnerType = Projectile.OwnerType.Player;

        // 近战攻击同样需要切换阵营，避免误伤玩家和其他随从
        if (_attackBehavior is MeleeAttack melee)
            melee.ownerType = Projectile.OwnerType.Player;

        // 接管死亡事件（EnemyCore.Assimilate 已清除原有订阅）
        if (_core.Health != null)
            _core.Health.OnDied += HandleDeath;
    }

    private void Update()
    {
        if (!_isActive || _player == null) return;
        if (_core.Health != null && _core.Health.IsDead) return;

        Vector2 pos = transform.position;
        Vector2 playerPos = _player.position;

        // 离玩家过远 → 直接传送到身边，防止掉队或被卡住
        float sqrDistToPlayer = (pos - playerPos).sqrMagnitude;
        if (sqrDistToPlayer > _maxTeleportDistance * _maxTeleportDistance)
        {
            _movement?.Teleport(playerPos);
            return;
        }

        // 寻找最近的敌人
        Transform nearestEnemy = FindNearestEnemy(pos);

        if (nearestEnemy != null)
        {
            Vector2 enemyPos = nearestEnemy.position;
            float distToEnemy = Vector2.Distance(pos, enemyPos);

            if (distToEnemy <= _attackRange)
            {
                _movement?.Stop();
                _attackBehavior?.TryAttack(nearestEnemy);

                // 尝试释放技能
                if (_skillManager != null && _skillManager.SkillInstances.Count > 0)
                {
                    Vector2 dir = (enemyPos - pos).normalized;
                    _skillManager.TryCastSkill(0, _core, dir);
                }
            }
            else
            {
                _movement?.MoveTowardsPosition(enemyPos);
            }
            return;
        }

        // 没有敌人 → 跟随玩家
        float distToPlayer = Vector2.Distance(pos, playerPos);
        if (distToPlayer > _followDistance)
        {
            _movement?.MoveTowardsPosition(playerPos);
        }
        else
        {
            _movement?.Stop();
        }
    }

    private Transform FindNearestEnemy(Vector2 center)
    {
        Collider2D[] hits = Physics2D.OverlapCircleAll(center, _detectionRange);
        Transform nearest = null;
        float minDist = float.MaxValue;

        foreach (var hit in hits)
        {
            if (!hit.CompareTag("Enemy")) continue;
            if (_player != null && hit.transform == _player) continue;

            float d = (hit.transform.position - (Vector3)center).sqrMagnitude;
            if (d < minDist)
            {
                minDist = d;
                nearest = hit.transform;
            }
        }

        return nearest;
    }

    private void OnRoomSwitchStarted(int fromRoomId, int toRoomId)
    {
        if (!_isActive || _player == null) return;

        // 1. 将随从切换到新房间的父节点，防止旧房间禁用时连带禁用它
        if (MapManager.Instance != null)
        {
            RoomRoot targetRoom = MapManager.Instance.GetRoom(toRoomId);
            if (targetRoom != null)
                transform.SetParent(targetRoom.transform, true);
        }

        // 2. 立即传送到玩家身边
        _movement?.Teleport(_player.position);
    }

    private void HandleDeath()
    {
        _isActive = false;

        // 禁用碰撞
        foreach (var col in GetComponentsInChildren<Collider2D>())
            col.enabled = false;

        _movement?.Stop();
        Destroy(gameObject, 0.5f);
    }
}

